CREATE TABLE public.dim_grupo_procedimento_manual (procedimento_nome text PRIMARY KEY, procedimento_chave text GENERATED ALWAYS AS (public.dre_feegow_normalizar_nome(procedimento_nome)) STORED UNIQUE, grupo_nome text NOT NULL, atualizado_em timestamptz NOT NULL DEFAULT now(), CHECK (btrim(procedimento_nome)<>'' AND btrim(grupo_nome)<>''));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.dim_grupo_procedimento_manual TO authenticated;
GRANT ALL ON public.dim_grupo_procedimento_manual TO service_role;
ALTER TABLE public.dim_grupo_procedimento_manual ENABLE ROW LEVEL SECURITY;
CREATE POLICY manual_grupo_leitura ON public.dim_grupo_procedimento_manual FOR SELECT TO authenticated USING (true);
CREATE POLICY manual_grupo_edicao ON public.dim_grupo_procedimento_manual FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.lab_producao_feegow ADD COLUMN grupo_fonte text;
CREATE OR REPLACE FUNCTION public.lab_grupo_exibicao(s text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path=public AS $$ SELECT CASE public.dre_feegow_normalizar_nome(s) WHEN '' THEN 'Não informado' WHEN 'nao informado' THEN 'Não informado' WHEN 'nao classificado' THEN 'Não informado' WHEN 'sem grupo' THEN 'Não informado' WHEN 'psquiatria' THEN 'Psiquiatria' WHEN 'psiquiatria' THEN 'Psiquiatria' WHEN 'reumatologia' THEN 'Reumatologia' WHEN 'nutricao' THEN 'Nutrição' WHEN 'usg' THEN 'USG' ELSE initcap(btrim(s)) END; $$;
CREATE OR REPLACE VIEW public.lab_vw_catalogo_grupos WITH (security_invoker=true) AS WITH codigos AS (SELECT grupo_id,max(grupo_nome) nome FROM public.lab_producao_feegow WHERE grupo_id>0 AND nullif(btrim(grupo_nome),'') IS NOT NULL AND grupo_nome !~ '^[0-9]+$' GROUP BY grupo_id HAVING count(DISTINCT public.lab_grupo_exibicao(grupo_nome))=1), fontes AS (SELECT d.procedimento_id,d.nome procedimento_nome,d.grupo_nome grupo_raw FROM public.lab_dim_procedimento d UNION ALL SELECT p.procedimento_id,p.nome,p.grupo FROM public.procedimentos p), resolvidos AS (SELECT f.procedimento_id,f.procedimento_nome,CASE WHEN f.grupo_raw ~ '^[0-9]+$' THEN c.nome ELSE f.grupo_raw END grupo_nome FROM fontes f LEFT JOIN codigos c ON f.grupo_raw=c.grupo_id::text) SELECT procedimento_id,procedimento_nome,grupo_nome FROM resolvidos WHERE public.lab_grupo_exibicao(grupo_nome)<>'Não informado' AND grupo_nome !~ '^[0-9]+$';
GRANT SELECT ON public.lab_vw_catalogo_grupos TO authenticated,service_role;
CREATE OR REPLACE VIEW public.lab_vw_grupo_por_id WITH (security_invoker=true) AS SELECT procedimento_id,max(grupo_nome) grupo_nome FROM public.lab_vw_catalogo_grupos GROUP BY procedimento_id HAVING count(DISTINCT public.lab_grupo_exibicao(grupo_nome))=1;
CREATE OR REPLACE VIEW public.lab_vw_grupo_por_nome WITH (security_invoker=true) AS SELECT public.dre_feegow_normalizar_nome(procedimento_nome) procedimento_chave,max(grupo_nome) grupo_nome FROM public.lab_vw_catalogo_grupos GROUP BY 1 HAVING count(DISTINCT public.lab_grupo_exibicao(grupo_nome))=1;
GRANT SELECT ON public.lab_vw_grupo_por_id,public.lab_vw_grupo_por_nome TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.lab_producao_completar_grupo() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE g text; BEGIN IF public.lab_grupo_exibicao(NEW.grupo_nome)<>'Não informado' THEN RETURN NEW; END IF; SELECT grupo_nome INTO g FROM public.lab_vw_grupo_por_id WHERE procedimento_id=NEW.procedimento_id; IF g IS NOT NULL THEN NEW.grupo_nome:=g; NEW.grupo_fonte:='catalogo_id'; RETURN NEW; END IF; SELECT grupo_nome INTO g FROM public.lab_vw_grupo_por_nome WHERE procedimento_chave=public.dre_feegow_normalizar_nome(NEW.procedimento_nome); IF g IS NOT NULL THEN NEW.grupo_nome:=g; NEW.grupo_fonte:='catalogo_nome'; RETURN NEW; END IF; SELECT grupo_nome INTO g FROM public.dim_grupo_procedimento_manual WHERE procedimento_chave=public.dre_feegow_normalizar_nome(NEW.procedimento_nome); IF g IS NOT NULL THEN NEW.grupo_nome:=g; NEW.grupo_fonte:='manual'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER lab_producao_completar_grupo BEFORE INSERT OR UPDATE OF grupo_nome,procedimento_nome,procedimento_id ON public.lab_producao_feegow FOR EACH ROW EXECUTE FUNCTION public.lab_producao_completar_grupo();
CREATE OR REPLACE VIEW public.vw_lab_producao_classificada WITH (security_invoker=true) AS SELECT p.id,p.feegow_id,p.paciente_id,p.paciente_nome,p.agendamento_id,p.data_execucao,p.hora_inicio,p.profissional_id,p.profissional_nome,p.procedimento_id,p.procedimento_nome,p.valor,p.convenio_nome,p.unidade_id,p.created_at,p.prontuario,p.id_transacao,p.n_guia_prestador,p.convenio_id,p.valor_pago,p.situacao,p.situacao_conta,p.grupo_id,public.lab_grupo_exibicao(CASE WHEN p.grupo_fonte='manual' OR public.lab_grupo_exibicao(p.grupo_nome)='Não informado' THEN coalesce(m.grupo_nome,p.grupo_nome) ELSE p.grupo_nome END) grupo_nome,p.tipo_procedimento,p.forma_pagamento,p.tipo_guia,p.grupo_nome grupo_nome_original,p.grupo_fonte FROM public.lab_producao_feegow p LEFT JOIN public.dim_grupo_procedimento_manual m ON m.procedimento_chave=public.dre_feegow_normalizar_nome(p.procedimento_nome) AND (p.grupo_fonte='manual' OR public.lab_grupo_exibicao(p.grupo_nome)='Não informado');
GRANT SELECT ON public.vw_lab_producao_classificada TO authenticated,service_role;
CREATE OR REPLACE VIEW public.vw_producao_sem_grupo WITH (security_invoker=true) AS SELECT procedimento_nome,procedimento_id,count(*) qtd,coalesce(sum(valor),0) valor FROM public.vw_lab_producao_classificada WHERE grupo_nome='Não informado' GROUP BY 1,2;
CREATE OR REPLACE VIEW public.vw_producao_sem_grupo_mensal WITH (security_invoker=true) AS SELECT date_trunc('month',data_execucao)::date mes,count(*) qtd,coalesce(sum(valor),0) valor FROM public.vw_lab_producao_classificada WHERE grupo_nome='Não informado' GROUP BY 1;
GRANT SELECT ON public.vw_producao_sem_grupo,public.vw_producao_sem_grupo_mensal TO authenticated,service_role;
-- Recreate only the function to change its output columns; no dependent objects or stored rows are removed.
DROP FUNCTION public.ia_producao(date,date,text,text,text,text);
CREATE FUNCTION public.ia_producao(p_inicio date,p_fim date,p_agrupar text DEFAULT 'profissional',p_profissional text DEFAULT NULL,p_convenio text DEFAULT NULL,p_grupo text DEFAULT NULL) RETURNS TABLE(chave text,qtd bigint,produzido numeric,faturado numeric,nao_faturado numeric,recebido numeric,ticket_medio numeric) LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public SET statement_timeout='8s' AS $$ DECLARE consulta text; dimensao text; BEGIN dimensao:=CASE p_agrupar WHEN 'profissional' THEN 'coalesce(p.profissional_nome,''Não informado'')' WHEN 'grupo' THEN 'p.grupo_nome' WHEN 'procedimento' THEN 'coalesce(p.procedimento_nome,''Não informado'')' WHEN 'origem' THEN 'public.lab_producao_origem(p.convenio_nome,p.convenio_id)' WHEN 'convenio' THEN 'CASE WHEN public.lab_producao_origem(p.convenio_nome,p.convenio_id)=''Não faturado'' THEN ''Não faturado'' ELSE coalesce(nullif(btrim(p.convenio_nome),''''),''Particular'') END' WHEN 'mes' THEN 'to_char(p.data_execucao,''YYYY-MM'')' WHEN 'dia' THEN 'p.data_execucao::text' WHEN 'forma_pagamento' THEN 'coalesce(p.forma_pagamento,''Não informado'')' ELSE '''Total''' END; consulta:='SELECT '||dimensao||' k,count(*),round(coalesce(sum(p.valor),0),2),round(coalesce(sum(p.valor) FILTER(WHERE p.situacao=''Faturado''),0),2),round(coalesce(sum(p.valor) FILTER(WHERE p.situacao=''Não Faturado''),0),2),round(coalesce(sum(p.valor_pago),0),2),round(coalesce(sum(p.valor),0)/nullif(count(*),0),2) FROM public.vw_lab_producao_classificada p WHERE p.data_execucao BETWEEN $1 AND $2'; IF p_profissional IS NOT NULL THEN consulta:=consulta||' AND public.lab_producao_texto(p.profissional_nome) LIKE ''%''||public.lab_producao_texto($3)||''%'''; END IF; IF p_convenio IS NOT NULL THEN consulta:=consulta||' AND CASE WHEN public.lab_producao_texto($4) IN (''particular'',''convenio'',''nao faturado'') THEN public.lab_producao_texto(public.lab_producao_origem(p.convenio_nome,p.convenio_id))=public.lab_producao_texto($4) ELSE public.lab_producao_texto(coalesce(nullif(p.convenio_nome,''''),''Particular'')) LIKE ''%''||public.lab_producao_texto($4)||''%'' END'; END IF; IF p_grupo IS NOT NULL THEN consulta:=consulta||' AND public.lab_producao_texto(p.grupo_nome) LIKE ''%''||public.lab_producao_texto(public.lab_grupo_exibicao($5))||''%'''; END IF; consulta:=consulta||' GROUP BY 1 ORDER BY '||CASE WHEN p_agrupar IN ('mes','dia') THEN '1' ELSE '3 DESC' END||' LIMIT 500'; RETURN QUERY EXECUTE consulta USING p_inicio,p_fim,p_profissional,p_convenio,p_grupo; END; $$;
REVOKE ALL ON FUNCTION public.ia_producao(date,date,text,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ia_producao(date,date,text,text,text,text) TO authenticated,service_role;